        about_hub: { c1_t:'Corporate Philosophy & Vision',c1_d:'UNIVERA\'s unwavering philosophy of focusing on aloe to stay by customers\' health.',c1_btn:'View →',c2_t:'Founding Story',c2_d:'The founder\'s conviction and 50-year journey to becoming an aloe specialty company.',c2_btn:'View →',c3_t:'Major Milestones',c3_d:'Key milestones from UNIVERA\'s founding in 1976 to its 50th anniversary in 2026.',c3_btn:'View →',c4_t:'Global Presence',c4_d:'Global capabilities starting from company-owned farms in 4 countries worldwide.',c4_btn:'View →',c5_t:'Certifications & Awards',c5_d:'Verified quality credentials including GMP, FDA GRAS, and 23 consecutive World-Class Product awards.',c5_btn:'View →',c6_t:'Directions',c6_d:'Location and contact information for UNIVERA headquarters in Cheonan.',c6_btn:'View →' },
        philosophy: { quote:'"To deliver nature\'s benefits to humanity, creating a healthy and beautiful world"',mission_h:'Mission — Nature\'s Benefits for Humanity',mission_p:'UNIVERA\'s mission is to deliver the purest benefits nature can offer. Our 50-year focus on aloe since 1976 stems from this mission.',vision_h:'Vision — The World\'s Eternal Leader in Natural Wellness',vision_p:'For UNIVERA, excellence means trust, not scale. Patents in 30 countries, 23 consecutive World-Class Product selections, farms in 4 countries spanning 37.33 million m² — milestones on the journey, not the destination.',values_h:'Core Values',values_sub:'Four principles UNIVERA has upheld for 50 years',val1_t:'Nature First',val1_d:'Our raw materials always begin with nature. Organic, pesticide-free cultivation and minimal processing preserve nature\'s original power.',val2_t:'Scientific Inquiry',val2_d:'We prove aloe\'s potential through science. The CAP Project (1992), Unigen research, and 104 patents are the results.',val3_t:'Accountable Quality',val3_d:'We manage every stage from cultivation to shipment. GMP, FDA GRAS, and IASC provide objective proof of this accountability.',val4_t:'Customer Health First',val4_d:'Every product starts with: "What health concern does this solve?" Our 9-category functional classification reflects this.',promise_h:'Brand Promise — Aloe, 50 Years from Now',promise_p:'UNIVERA marks its 50th anniversary in 2026. Through half a century of trends, UNIVERA has never let go of aloe.',btn_story:'Read Our Founding Story',btn_history:'View Major Milestones' },
        story: { why_h:'Why Aloe?',why_p1:'Aloe vera is a complex plant containing over 200 bioactive substances. Despite attention across many health areas, no company had scientifically standardized its benefits.',why_p2:'UNIVERA resolved not to simply sell aloe. By growing, analyzing, and producing it directly, we set out to unlock aloe\'s true potential.',quote:'"What matters is not what ingredients you use, but how deeply you understand them. UNIVERA has spent 50 years focused on understanding aloe."',world_h:'Why We Went Global',world_p1:'Good aloe grows in good environments. UNIVERA crossed borders seeking optimal conditions — Mexico, Dominican Republic, USA, and Korea — building 37.33 million m² of company-owned farms.',world_p2:'This area is about 12 times the size of Yeouido. We grow our own because we take full responsibility for quality from start to finish.',now_h:'50 Years Later',now_p1:'In 2026, UNIVERA celebrates its 50th anniversary. Through decades of changing trends, one thing has never changed: our promise to stay by customers\' health through aloe.',now_p2:'23 consecutive World-Class Product selections, Presidential Commendation, GMP & FDA GRAS — these are the results of 50 years of keeping that first promise.',stat1_n:'1976',stat1_l:'Year Founded',stat2_n:'4 Countries',stat2_l:'Company-Owned Global Farms',stat3_n:'50+ Years',stat3_l:'Aloe Research',btn_history:'View Major Milestones',btn_aloe:'Aloe Quick Guide',lead:'One company has focused on a single ingredient for 50 years. Going deep on aloe rather than chasing trends — that choice created today s UNIVERA.',begin_h:'1976 — Starting from One Belief',begin_p1:'In 1976, when aloe was still unfamiliar in Korea, UNIVERA s founder established the company with a conviction: find the answer in nature.',begin_p2:'Deeply understanding one ingredient comes first. This firm belief guided 50 years of the journey.' },
        history: { intro:'Key milestones from UNIVERA\'s founding to the present',dec_1970s:'1970s',dec_1980s:'1980s',dec_1990s:'1990s',dec_2000s:'2000s',dec_2020s:'2020s',y1976_t:'First Successful Aloe Trial Cultivation in Korea',y1976_d:'Korea\'s first successful aloe vera trial cultivation.',y1981_t:'Banwol Farm No.1 Established — 200,000 Aloe Plants',y1981_d:'First step toward vertical integration.',y1984_t:'Namyang Aloe Nongsan Founded',y1984_d:'Official corporate history begins.',y1984_tag:'Company Founded',y1988_t:'IASC Membership · US Subsidiary Alocop Established',y1988_d:'Joined IASC; established US subsidiary.',y1988_tag:'IASC · Global',y1989_t:'Mexico Tampico Farm · Aloe Research Foundation',y1989_d:'First overseas company-owned farm opened.',y1989_tag:'Overseas Farm',y1990_t:'Converted to Corp. · Korea\'s First KGMP Factory',y1990_d:'Korea\'s first KGMP-certified factory completed.',y1990_tag:'KGMP',y1991_t:'Jincheon Factory No.2 Completed',y1991_d:'Production capacity expanded.',y1992_t:'CAP Project — Aloe Drug Development',y1992_d:'Collaborative Aloe Project launched.',y1992_tag:'CAP Project',y1993_t:'President Lee Byeong-hun Appointed',y1996_t:'Unigen Established · Cheonggang College Founded',y1996_d:'Aloe research subsidiary Unigen established.',y1996_tag:'Unigen Founded',y2003_t:'First World-Class Product — 23 Consecutive Years',y2003_d:'First selection by Ministry of Trade; 23 consecutive years through 2025.',y2003_tag:'World-Class Product',y2022_t:'Super Gel W — Selected as Hit Product',y2022_tag:'Hit Product',y2025_t:'Presidential Commendation · 23rd Consecutive World-Class Product',y2025_tag:'Presidential Award',y2026_t:'50th Anniversary — Nationwide Experience Events',y2026_tag:'50th Anniversary',y1993_d:'President Lee Byeong-hun was appointed, leading UNIVERA globalization and R&D.',y2022_d:'Super Gel W selected as hit product — aloe gel recognized by consumers.',y2023_t:'New CEO Kim Gyo-man Appointed',y2023_d:'CEO Kim Gyo-man appointed August 2023, leading new strategy toward 50th anniversary.',y2025_d:'Presidential commendation June 2025 for aloe industry contributions. 23rd consecutive World-Class Product.',y2026_d:'50 years since Korea first aloe cultivation 1976. Nationwide events April-May 2026 celebrated 50th anniversary.',note:'※ Some milestones subject to update after departmental verification.',btn_story:'View Founding Story',btn_certs:'All Certifications & Awards' },
